import Fastify from "fastify";

type Product = { id: string; name: string; price: number };
const products: Product[] = [];

export const app = Fastify({ logger: false });

async function catalog(app: any) {
    // TODO: validate the body, reject extra fields, and register the plugin
    app.post("/products", async function createProduct(request, reply) {
        products.push(request.body);
        return reply.status(201).send(request.body);
    });
}

app.register(catalog);

