import Fastify, { type FastifyInstance } from "fastify";

export const app = Fastify({ logger: false });

const catalog = async function catalog(app: FastifyInstance) {
    app.addHook("onRequest", async function authenticate(request) {
        request.user = { role: "admin" };
    });
};

app.register(catalog);

app.post("/products", {
    schema: {
        body: {
            type: "object",
            required: ["name", "price"],
            properties: {
                name: { type: "string" },
                price: { type: "number" },
            },
        },
    },
}, async function createProduct(request, reply) {
    return reply.status(201).send(request.body);
});
